using System;
using System.Collections.ObjectModel;
using Avalonia;
using Avalonia.Controls;
using Avalonia.Controls.ApplicationLifetimes;
using Avalonia.Data.Core.Plugins;
using Avalonia.Markup.Xaml;
using Avalonia.Styling;
using CommunityToolkit.Mvvm.ComponentModel;
using CommunityToolkit.Mvvm.Input;

namespace AvaloniaTodo;

// ===== Model =====
public partial class TodoItem : ObservableObject
{
    [ObservableProperty] private string _title = "";
    [ObservableProperty] private bool _isDone;
}

// ===== ViewModel =====
public partial class MainViewModel : ObservableObject
{
    [ObservableProperty] private string _newTitle = "";

    public ObservableCollection<TodoItem> Items { get; } = new()
    {
        new() { Title = "学 Avalonia 依赖属性体系" },
        new() { Title = "对比 MAUI 自绘 vs 原生取舍" }
    };

    [RelayCommand(CanExecute = nameof(CanAdd))]
    private void Add()
    {
        Items.Add(new TodoItem { Title = NewTitle });
        NewTitle = "";
    }

    private bool CanAdd => !string.IsNullOrWhiteSpace(NewTitle);

    [RelayCommand]
    private void Remove(TodoItem? item)
    {
        if (item != null) Items.Remove(item);
    }
}

// ===== 自定义控件：StyledProperty vs DirectProperty =====
public class ScoreControl : Control
{
    // StyledProperty：可被样式作用（主题色、动画）
    public static readonly StyledProperty<string> LabelProperty =
        AvaloniaProperty.Register<ScoreControl, string>(nameof(Label), "Score");

    public string Label
    {
        get => GetValue(LabelProperty);
        set => SetValue(LabelProperty, value);
    }

    // DirectProperty：高频更新路径，跳过样式系统
n    private double _value;
    public static readonly DirectProperty<ScoreControl, double> ValueProperty =
        AvaloniaProperty.RegisterDirect<ScoreControl, double>(
            nameof(Value), o => o.Value, (o, v) => o.Value = v);

    public double Value
    {
        get => _value;
        set => SetAndRaise(ValueProperty, ref _value, value);
    }
}

// ===== App =====
public class App : Application
{
    public override void Initialize() => AvaloniaXamlLoader.Load(this);

    public override void OnFrameworkInitializationCompleted()
    {
        if (ApplicationLifetime is IClassicDesktopStyleApplicationLifetime desktop)
        {
            desktop.MainWindow = new MainWindow
            {
                DataContext = new MainViewModel()
            };
        }
        base.OnFrameworkInitializationCompleted();
    }
}

// ===== Program =====
class Program
{
    [STAThread]
    public static void Main(string[] args)
        => AppBuilder.Configure<App>()
            .UsePlatformDetect()
            .LogToTrace()
            .StartWithClassicDesktopLifetime(args);
}
